BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷86·高祖皇后李氏·流放及病逝的引书注文", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf28044c4a9f9f68546150cdc9ab0e618a0e3541/content/books/zizhi-tongjian/vol-289/year-0950/part-05/sources/library/jiuwudaishi-086-jin-empress-exile/source.txt", "note": "《旧五代史》卷86·高祖皇后李氏·流放及病逝的引书注文，段落 jiu-wudaishi-205deb4a7860-p002062；已核上下文及传主，纸本及异文待核。", "id": "a33a1972-1a60-53d1-8d7e-4fb8c8278036"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf28044c4a9f9f68546150cdc9ab0e618a0e3541/content/books/zizhi-tongjian/vol-289/year-0950/part-05/sources/library/jiuwudaishi-103-october-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年十月，段落 jiu-wudaishi-205deb4a7860-p002493；已核上下文及传主，纸本及异文待核。", "id": "0f47a23d-13f3-5185-a0cc-ceb3e462e903"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年九月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf28044c4a9f9f68546150cdc9ab0e618a0e3541/content/books/zizhi-tongjian/vol-289/year-0950/part-05/sources/library/jiuwudaishi-103-september-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年九月，段落 jiu-wudaishi-205deb4a7860-p002492；已核上下文及传主，纸本及异文待核。", "id": "3c46dec2-6415-5d48-8fce-31cec81d0721"}, {"title": "新五代史·卷64·后蜀世家·王室册封", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf28044c4a9f9f68546150cdc9ab0e618a0e3541/content/books/zizhi-tongjian/vol-289/year-0950/part-05/sources/library/xinwudaishi-064-shu-royal-titles/source.txt", "note": "《新五代史》卷64·后蜀世家·王室册封，段落 xin-wudaishi-b08f244b9241-p003242；已核上下文及传主，纸本及异文待核。", "id": "1f93ff5e-9538-524c-a37b-ab077dfe3d69"}, {"title": "资治通鉴·卷289·乾祐三年·闰月与六月等", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6cb30a738bec3fb5634ff2481280a4833869f788/content/books/zizhi-tongjian/vol-289/year-0950/part-04/sources/library/tongjian-289-950-intercalary-month/source.txt", "note": "《资治通鉴》卷289·乾祐三年·闰月与六月等，段落 zizhi-tongjian-a63549944a71-p003429；已核上下文及传主，纸本及异文待核。", "id": "34e5229e-bf1a-5a50-b15a-3287f46ac4fa"}, {"title": "新五代史·卷66·楚世家·仆射洲之战及后续", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/xinwudaishi-066-pushezhou/source.txt", "note": "《新五代史》卷66·楚世家·仆射洲之战及后续，段落 xin-wudaishi-b08f244b9241-p003329；已核上下文及传主，纸本及异文待核。", "id": "1de76302-3d97-5251-886d-6cba3e293c85"}, {"title": "新五代史·卷62·南唐世家·陈诲后续活动校核", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/xinwudaishi-062-chen-hui-later/source.txt", "note": "《新五代史》卷62·南唐世家·八年陈诲参战，段落 xin-wudaishi-b08f244b9241-p003145；仅作946年死亡记载的时序异说校核，不提前录入后续战事；纸本及异文待核。", "id": "a90839a2-9053-5777-b22f-e70b09603b35"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "陈璠（马希广将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 950, "description": "马希广的指挥使。950年受命抵抗攻向益阳的军队，在淹溪作战失败身亡。与晚唐同名陈璠是否有联系没有证据，分开建档，出生年未载。", "biography": null, "status": "draft", "id": "38bf2d85-6e5c-5485-838b-04b8bb71522c"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "马先进", "aliases": ["馬先進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州将领。950年南唐进军福州时被陈诲俘获。《资治通鉴》把被俘记在查文徽到达福州之前；《新五代史》叙在查文徽被俘之后，还记李璟把他送回吴越。时序差异保留。生卒年未载。", "biography": null, "status": "draft", "id": "ae093500-71f0-5c78-bc13-e94eb49ccb1c"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "张延嗣", "aliases": ["張延嗣"], "era": "五代十国", "birth_year": null, "death_year": 950, "description": "迪田镇将。950年八月戊戌，迪田被马希萼所遣军队攻破时被杀。出生年及其他经历未载。", "biography": null, "status": "draft", "id": "dff897f7-abfb-59a3-8708-5d3146b54d8a"}, {"name": "黄处超", "aliases": ["黃處超"], "era": "五代十国", "birth_year": null, "death_year": 950, "description": "马希广的指挥使。950年受命救援迪田方向，在作战失败后身亡。具体死亡日未另列，出生年未载。", "biography": null, "status": "draft", "id": "d9ff0936-098b-5825-bcb0-cd9562e36eac"}, {"name": "崔洪琏", "aliases": ["崔洪璉", "崔珙璉", "崔珙琏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的牙内指挥使。950年八月条下率七千兵屯玉潭。《新五代史》同职、同兵数、同驻地人物写崔珙璉，保留异字。生卒年未载。", "biography": null, "status": "draft", "id": "779075a2-a9a5-5342-924f-359f8f686d1f"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "孟仁毅", "aliases": ["孟仕毅"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟昶的弟弟。950年八月获封夔王。《资治通鉴》所用电子本写仕毅，《新五代史》同一夔王写仁毅，按封号和亲属身份对应为同一人，原字保留。生卒年未载。", "biography": null, "status": "draft", "id": "b6e10d68-5fc5-5418-9ac0-31b46f762875"}, {"name": "孟仁贽", "aliases": ["孟仁贄"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟昶的弟弟。950年八月庚子获封雅王，《新五代史》也记同一雅王册封。生卒年未载。", "biography": null, "status": "draft", "id": "3271fd3b-a2fd-50c3-9f6a-0ccedb3ac5e3"}, {"name": "孟仁裕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟昶的弟弟。950年八月《资治通鉴》记封为彭王，《新五代史》相关册封却写嘉王，王号差异保留。生卒年未载。", "biography": null, "status": "draft", "id": "c221d5a3-ae71-5fed-b592-62eee0a2cc16"}, {"name": "孟仁操", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟昶的弟弟。950年八月庚子，《资治通鉴》记获封嘉王。《新五代史》相关册封未列其名，未凭省略认定不存在。生卒年未载。", "biography": null, "status": "draft", "id": "3f303bc3-c187-5c88-ad67-9a9b97d35522"}, {"name": "孟玄喆", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟昶的儿子。950年八月己酉获封秦王，《新五代史》也记封秦王并判六军事。生卒年未载。", "biography": null, "status": "draft", "id": "e958b6c3-dcfb-55bf-9f24-cfc249760dcd"}, {"name": "孟玄珏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟昶的儿子。950年八月己酉获封褒王，《新五代史》相关记载称他为次子。生卒年未载。", "biography": null, "status": "draft", "id": "5a4a5d5c-81f9-54ac-b8b3-5bcc802861fc"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "冯氏（石重贵后）", "aliases": ["吴国夫人冯氏", "馮氏（石重贵后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯濛的女儿、冯玉的妹妹。先嫁石重胤，夫死后守寡；石敬瑭去世后被石重贵纳入宫中，943年十月戊申由吴国夫人立为皇后，随后参与政务。具体个人名字与生卒年未载。", "biography": null, "status": "draft", "id": "a9036cf2-4b6b-5883-a952-511979eb35f7"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "何敬洙", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐天威都虞候。945年李璟任他为建州行营招讨马步都指挥使，与祖全恩、姚凤率数千兵增援查文徽，攻建州。生卒年本段未载。", "biography": null, "status": "draft", "id": "775d369d-2375-51d0-bcd1-b59c3a78d7c1"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

